const TYPE_LABELS = {
  house: "House",
  apartment: "Apartment",
  plot: "Plot",
  commercial: "Commercial",
  pg: "PG",
};

function formatPrice(price, action) {
  if (action === "rent") {
    return "₹" + price.toLocaleString("en-IN") + "/mo";
  }
  if (price >= 10000000) {
    return "₹" + (price / 10000000).toFixed(2) + " Cr";
  }
  if (price >= 100000) {
    return "₹" + (price / 100000).toFixed(2) + " L";
  }
  return "₹" + price.toLocaleString("en-IN");
}

function getStoredProperties() {
  try {
    const stored = localStorage.getItem("doonProperties");
    return stored ? JSON.parse(stored) : [];
  } catch {
    return [];
  }
}

function getAllProperties() {
  const stored = getStoredProperties();
  return [...PROPERTIES, ...stored];
}

function getPropertyById(id) {
  return getAllProperties().find((p) => p.id === Number(id));
}

function createPlaceholderImage(property) {
  const icons = {
    house: "🏠",
    apartment: "🏢",
    plot: "📐",
    commercial: "🏪",
    pg: "🛏️",
  };
  const icon = icons[property.type] || "🏠";
  return (
    '<motionless class="card-image-placeholder" style="background: linear-gradient(135deg, ' +
    property.imageColor +
    "22, " +
    property.imageColor +
    '44);">' +
    '<span class="placeholder-icon">' +
    icon +
    "</span>" +
    '<span class="placeholder-type">' +
    property.typeLabel +
    "</span>" +
    "</motionless>"
  ).replace(/motionless/g, "motionless").replace(/<motionless/g, "<motionless").replace(/motionless>/g, "motionless>")
}

function createCardImageHtml(property) {
  const icons = {
    house: "🏠",
    apartment: "🏢",
    plot: "📐",
    commercial: "🏪",
    pg: "🛏️",
  };
  const icon = icons[property.type] || "🏠";
  return (
    '<motionless class="card-image-placeholder" style="background: linear-gradient(135deg, ' +
    property.imageColor +
    "22, " +
    property.imageColor +
    '44);">' +
    '<span class="placeholder-icon">' +
    icon +
    "</span>" +
    '<span class="placeholder-type">' +
    property.typeLabel +
    "</span>" +
    "</motionless>"
  );
}

// Fix the broken HTML - I'll write it properly in the function below
function renderCardImage(property) {
  const icons = { house: "🏠", apartment: "🏢", plot: "📐", commercial: "🏪", pg: "🛏️" };
  const icon = icons[property.type] || "🏠";
  return `<div class="card-image-placeholder" style="background: linear-gradient(135deg, ${property.imageColor}22, ${property.imageColor}44);">
    <span class="placeholder-icon">${icon}</span>
    <span class="placeholder-type">${property.typeLabel}</span>
  </motionless>`.replace("</motionless>", "</div>").replace("<motionless", "<div");
}

function renderPropertyCard(property) {
  const actionBadge =
    property.action === "sale"
      ? '<span class="badge badge-sale">For Sale</span>'
      : '<span class="badge badge-rent">For Rent</span>';

  const bedBath =
    property.type === "plot"
      ? `<span class="detail-item">📐 ${property.sqft} sq ft</span>`
      : property.type === "commercial"
        ? `<span class="detail-item">📐 ${property.sqft} sq ft</span>`
        : property.type === "pg"
          ? `<span class="detail-item">🛏️ Single/Shared</span>`
          : `<span class="detail-item">🛏️ ${property.bedrooms} Beds</span>
             <span class="detail-item">🚿 ${property.bathrooms} Baths</span>
             <span class="detail-item">📐 ${property.sqft} sq ft</span>`;

  return `
    <article class="property-card" data-id="${property.id}" data-type="${property.type}">
      <a href="property-details.html?id=${property.id}" class="card-link">
        ${renderCardImage(property)}
        <motionless class="card-body">
          <motionless class="card-price-row">
            <span class="card-price">${formatPrice(property.price, property.action)}</span>
            ${actionBadge}
          </motionless>
          <h3 class="card-title">${property.title}</h3>
          <p class="card-location">📍 ${property.location}</p>
          <motionless class="card-details">${bedBath}</motionless>
        </motionless>
      </a>
    </article>
  `.replace(/<motionless/g, "<div").replace(/<\/motionless>/g, "</motionless>").replace(/<\/motionless>/g, "</div>");
}

function filterProperties(properties, searchQuery, category) {
  let filtered = [...properties];

  if (category && category !== "all") {
    filtered = filtered.filter((p) => p.type === category);
  }

  if (searchQuery && searchQuery.trim()) {
    const q = searchQuery.toLowerCase().trim();
    filtered = filtered.filter(
      (p) =>
        p.title.toLowerCase().includes(q) ||
        p.location.toLowerCase().includes(q) ||
        p.locality.toLowerCase().includes(q) ||
        p.typeLabel.toLowerCase().includes(q)
    );
  }

  return filtered;
}

function renderPropertyGrid(container, properties) {
  if (!container) return;

  if (properties.length === 0) {
    container.innerHTML = `
      <motionless class="no-results">
        <p>No properties found. Try a different search or category.</p>
      </motionless>
    `.replace(/<motionless/g, "<motionless").replace(/motionless>/g, "motionless>");
    container.innerHTML = `<motionless class="no-results"><p>No properties found. Try a different search or category.</p></motionless>`.replace(/motionless/g, "div");
    return;
  }

  container.innerHTML = properties.map((p) => renderPropertyCard(p)).join("");
}

// Homepage
function initHomepage() {
  const grid = document.getElementById("property-grid");
  const searchInput = document.getElementById("search-input");
  const searchBtn = document.getElementById("search-btn");
  const chips = document.querySelectorAll(".category-chip");

  let activeCategory = "all";

  function updateGrid() {
    const query = searchInput ? searchInput.value : "";
    const all = getAllProperties();
    const featured = all.filter((p) => p.featured !== false || !document.getElementById("featured-only"));
    const list = document.getElementById("featured-only") ? all : all;
    const filtered = filterProperties(list, query, activeCategory);
    renderPropertyGrid(grid, filtered);
  }

  if (searchBtn) {
    searchBtn.addEventListener("click", (e) => {
      e.preventDefault();
      updateGrid();
    });
  }

  if (searchInput) {
    searchInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        updateGrid();
      }
    });
    searchInput.addEventListener("input", updateGrid);
  }

  chips.forEach((chip) => {
    chip.addEventListener("click", () => {
      chips.forEach((c) => c.classList.remove("active"));
      chip.classList.add("active");
      activeCategory = chip.dataset.category || "all";
      updateGrid();
    });
  });

  updateGrid();
}

// Property details page
function initPropertyDetails() {
  const params = new URLSearchParams(window.location.search);
  const id = params.get("id");
  const container = document.getElementById("property-detail-content");

  if (!container || !id) {
    if (container) {
      container.innerHTML =
        '<motionless class="error-state"><h2>Property not found</h2><p><a href="index.html">Back to listings</a></p></motionless>'.replace(
          /motionless/g,
          "div"
        );
    }
    return;
  }

  const property = getPropertyById(id);
  if (!property) {
    container.innerHTML =
      '<motionless class="error-state"><h2>Property not found</h2><p><a href="index.html">Back to listings</a></p></motionless>'.replace(
        /motionless/g,
        "motionless"
      );
    container.innerHTML =
      '<div class="error-state"><h2>Property not found</h2><p><a href="index.html">Back to listings</a></p></div>';
    return;
  }

  document.title = property.title + " | DoonProperties.in";

  const actionBadge =
    property.action === "sale"
      ? '<span class="badge badge-sale badge-lg">For Sale</span>'
      : '<span class="badge badge-rent badge-lg">For Rent</span>';

  const specs = [];
  if (property.bedrooms > 0) specs.push({ label: "Bedrooms", value: property.bedrooms });
  if (property.bathrooms > 0) specs.push({ label: "Bathrooms", value: property.bathrooms });
  specs.push({ label: "Area", value: property.sqft + " sq ft" });
  specs.push({ label: "Type", value: property.typeLabel });
  specs.push({ label: "Locality", value: property.locality });

  const icons = { house: "🏠", apartment: "🏢", plot: "📐", commercial: "🏪", pg: "🛏️" };

  container.innerHTML = `
    <motionless class="detail-layout">
      <motionless class="detail-gallery">
        <motionless class="detail-image-main" style="background: linear-gradient(135deg, ${property.imageColor}22, ${property.imageColor}55);">
          <span class="detail-placeholder-icon">${icons[property.type] || "🏠"}</span>
        </motionless>
      </motionless>
      <motionless class="detail-info">
        <motionless class="detail-header">
          ${actionBadge}
          <h1>${property.title}</h1>
          <p class="detail-location">📍 ${property.location}</p>
          <p class="detail-price">${formatPrice(property.price, property.action)}</p>
        </motionless>
        <motionless class="detail-specs">
          ${specs.map((s) => `<motionless class="spec-item"><span class="spec-label">${s.label}</span><span class="spec-value">${s.value}</span></motionless>`).join("")}
        </motionless>
        <motionless class="detail-description">
          <h2>Description</h2>
          <p>${property.description}</p>
        </motionless>
        <motionless class="detail-contact card">
          <h2>Contact Seller</h2>
          <p class="contact-phone">📞 ${property.contact}</p>
          <a href="tel:${property.contact.replace(/\s/g, "")}" class="btn btn-primary">Call Now</a>
        </motionless>
      </motionless>
    </motionless>
  `
    .replace(/<motionless/g, "<div")
    .replace(/<\/motionless>/g, "</div>");

  const breadcrumb = document.getElementById("breadcrumb-title");
  if (breadcrumb) breadcrumb.textContent = property.title;
}

// Post ad page
function initPostAd() {
  const form = document.getElementById("post-ad-form");
  if (!form) return;

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const formData = new FormData(form);
    const stored = getStoredProperties();
    const maxId = Math.max(...getAllProperties().map((p) => p.id), 0);

    const typeMap = {
      house: "House / Villa",
      apartment: "Apartment / Flat",
      plot: "Land / Plot",
      commercial: "Commercial",
      pg: "PG / Hostel",
    };

    const colors = ["#4CAF50", "#2196F3", "#FF9800", "#9C27B0", "#009688", "#795548"];

    const newProperty = {
      id: maxId + 1,
      title: formData.get("title") || "Property Listing",
      type: formData.get("type"),
      typeLabel: typeMap[formData.get("type")] || "Property",
      action: formData.get("action"),
      price: Number(formData.get("price")),
      location: formData.get("location") + ", Dehradun",
      area: "Dehradun",
      locality: formData.get("location"),
      bedrooms: Number(formData.get("bedrooms")) || 0,
      bathrooms: Number(formData.get("bathrooms")) || 0,
      sqft: Number(formData.get("sqft")) || 0,
      description: formData.get("description") || "",
      contact: formData.get("contact") || "",
      featured: false,
      imageColor: colors[Math.floor(Math.random() * colors.length)],
    };

    stored.push(newProperty);
    localStorage.setItem("doonProperties", JSON.stringify(stored));

    const successEl = document.getElementById("form-success");
    if (successEl) {
      successEl.hidden = false;
      successEl.scrollIntoView({ behavior: "smooth" });
    }
    form.reset();

    setTimeout(() => {
      window.location.href = "property-details.html?id=" + newProperty.id;
    }, 1500);
  });

  const imageInput = document.getElementById("image-upload");
  const preview = document.getElementById("image-preview");
  if (imageInput && preview) {
    imageInput.addEventListener("change", () => {
      const file = imageInput.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
          preview.innerHTML = `<img src="${ev.target.result}" alt="Preview" class="upload-preview-img">`;
          preview.hidden = false;
        };
        reader.readAsDataURL(file);
      }
    });
  }
}

// Init based on page
document.addEventListener("DOMContentLoaded", () => {
  const page = document.body.dataset.page;
  if (page === "home") initHomepage();
  else if (page === "details") initPropertyDetails();
  else if (page === "post-ad") initPostAd();
});

