.contact-phone {
  font-size: 1.1rem;
  font-weight: 600;
  margin-bottom: 1rem;
}

.error-state {
  text-align: center;
  padding: 4rem 1rem;
  background: var(--white);
  border-radius: var(--radius);
}

/* Post ad form */
.form-page {
  max-width: 720px;
  margin: 0 auto;
}

.form-card {
  background: var(--white);
  border-radius: var(--radius);
  padding: 1.5rem;
  box-shadow: var(--shadow);
}

.form-card h1 {
  font-size: 1.5rem;
  margin-bottom: 0.35rem;
}

.form-card > p {
  color: var(--text-muted);
  font-size: 0.9rem;
  margin-bottom: 1.5rem;
}

.form-group {
  margin-bottom: 1.25rem;
}

.form-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 0.4rem;
  color: var(--text);
}

.form-group label .required {
  color: #d32f2f;
}

.form-group input,
.form-group select,
.form-group textarea {
  width: 100%;
  padding: 0.75rem 1rem;
  font-family: var(--font);
  font-size: 0.95rem;
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  background: var(--white);
  color: var(--text);
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-group input:focus,
.form-group select:focus,
.form-group textarea:focus {
  outline: none;
  border-color: var(--primary);
  box-shadow: 0 0 0 3px rgba(46, 125, 50, 0.15);
}

.form-group textarea {
  min-height: 120px;
  resize: vertical;
}

.form-row {
  display: grid;
  gap: 1rem;
}

@media (min-width: 500px) {
  .form-row {
    grid-template-columns: 1fr 1fr;
  }
}

.form-row-3 {
  grid-template-columns: 1fr;
}

@media (min-width: 500px) {
  .form-row-3 {
    grid-template-columns: repeat(3, 1fr);
  }
}

.radio-group {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.radio-group label {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  font-weight: 500;
  cursor: pointer;
}

.radio-group input[type="radio"] {
  width: auto;
  accent-color: var(--primary);
}

.file-upload {
  border: 2px dashed var(--border);
  border-radius: var(--radius-sm);
  padding: 1.5rem;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.2s, background 0.2s;
}

.file-upload:hover {
  border-color: var(--primary);
  background: rgba(46, 125, 50, 0.04);
}

.file-upload input {
  display: none;
}

.file-upload p {
  color: var(--text-muted);
  font-size: 0.875rem;
  margin-top: 0.5rem;
}

.upload-preview-img {
  max-height: 200px;
  margin: 0 auto;
  border-radius: var(--radius-sm);
}

.form-success {
  background: rgba(46, 125, 50, 0.1);
  border: 1px solid var(--primary);
  color: var(--primary-dark);
  padding: 1rem;
  border-radius: var(--radius-sm);
  margin-bottom: 1rem;
  font-weight: 500;
}

.form-actions {
  display: flex;
  gap: 0.75rem;
  flex-wrap: wrap;
  margin-top: 1.5rem;
}

/* Footer */
.site-footer {
  background: #263238;
  color: #b0bec5;
  margin-top: auto;
  padding: 2rem 1rem 1.5rem;
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  gap: 1.5rem;
}

@media (min-width: 768px) {
  .footer-inner {
    grid-template-columns: 2fr 1fr 1fr;
  }
}

.footer-brand .logo {
  color: white;
  margin-bottom: 0.75rem;
}

.footer-brand p {
  font-size: 0.875rem;
  line-height: 1.6;
  max-width: 320px;
}

.footer-links h4 {
  color: white;
  font-size: 0.9rem;
  margin-bottom: 0.75rem;
}

.footer-links ul {
  list-style: none;
}

.footer-links li {
  margin-bottom: 0.4rem;
}

.footer-links a {
  color: #b0bec5;
  font-size: 0.875rem;
}

.footer-links a:hover {
  color: var(--secondary);
}

.footer-bottom {
  max-width: var(--max-width);
  margin: 1.5rem auto 0;
  padding-top: 1rem;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  text-align: center;
  font-size: 0.8rem;
}

/* Mobile nav */
@media (max-width: 768px) {
  .menu-toggle {
    display: block;
  }

  .nav-links {
    position: fixed;
    top: var(--header-height);
    left: 0;
    right: 0;
    background: var(--white);
    flex-direction: column;
    padding: 1rem;
    box-shadow: var(--shadow);
    transform: translateY(-120%);
    opacity: 0;
    visibility: hidden;
    transition: transform 0.25s, opacity 0.25s, visibility 0.25s;
  }

  .nav-links.open {
    transform: translateY(0);
    opacity: 1;
    visibility: visible;
  }

  .nav-links .btn {
    width: 100%;
  }

  .search-bar {
    flex-direction: column;
  }

  .search-bar .btn {
    border-radius: 0 0 var(--radius) var(--radius);
    width: 100%;
  }

  .types-strip {
    display: none;
  }
}

