function formatPrice(property) {
  const price = property.price;

  if (property.type === "pg") {
    const sharing =
      property.pgSharing === "single" ? "single" : property.pgSharing === "sharing" ? "sharing" : "single/sharing";
    return "₹" + price.toLocaleString("en-IN") + " / month (" + sharing + ")";
  }

  if (property.action === "rent") {
    return "₹" + price.toLocaleString("en-IN") + " / month";
  }

  if (price >= 10000000) {
    return "₹" + price.toLocaleString("en-IN") + " (" + (price / 10000000).toFixed(2) + " Cr)";
  }
  if (price >= 100000) {
    return "₹" + price.toLocaleString("en-IN") + " (" + (price / 100000).toFixed(2) + " L)";
  }
  return "₹" + price.toLocaleString("en-IN");
}

function getTransactionLabel(property) {
  if (property.type === "pg") return "PG / Guesthouse";
  if (property.action === "sale") return "For Sale";
  return "For Rent";
}

function getActionBadge(property, large = false) {
  const base = large ? "badge badge-lg" : "badge";
  if (property.type === "pg") {
    return `<span class="${base} badge-pg">PG/GUESTHOUSE</span>`;
  }
  if (property.action === "sale") {
    return `<span class="${base} badge-sale">FOR SALE</span>`;
  }
  return `<span class="${base} badge-rent">FOR RENT</span>`;
}

function getStoredProperties() {
  try {
    const stored = localStorage.getItem("doonProperties");
    return stored ? JSON.parse(stored) : [];
  } catch {
    return [];
  }
}

function getAllProperties() {
  return [...PROPERTIES, ...getStoredProperties()];
}

function getPropertyById(id) {
  return getAllProperties().find((p) => p.id === Number(id));
}

function cardImageHtml(property) {
  const icons = { house: "🏠", apartment: "🏢", plot: "📐", commercial: "🏪", pg: "🛏️" };
  const icon = icons[property.type] || "🏠";
  return `<div class="card-image-placeholder" style="background: linear-gradient(135deg, ${property.imageColor}22, ${property.imageColor}44);">
    <span class="placeholder-icon">${icon}</span>
    <span class="placeholder-type">${property.typeLabel}</span>
  </div>`;
}

function cardDetailsHtml(property) {
  if (property.type === "plot") {
    return `<span class="detail-item">📐 ${property.sqft} sq ft</span>`;
  }
  if (property.type === "commercial") {
    return `<span class="detail-item">📐 ${property.sqft} sq ft</span>`;
  }
  if (property.type === "pg") {
    const sharing = property.pgSharing === "single" ? "Single" : property.pgSharing === "sharing" ? "Sharing" : "Single/Shared";
    return `<span class="detail-item">🛏️ ${sharing}</span><span class="detail-item">📐 ${property.sqft} sq ft</span>`;
  }
  return `<span class="detail-item">🛏️ ${property.bedrooms} Beds</span>
    <span class="detail-item">🚿 ${property.bathrooms} Baths</span>
    <span class="detail-item">📐 ${property.sqft} sq ft</span>`;
}

function renderPropertyCard(property) {
  const priceClass = property.action === "sale" ? "card-price card-price-sale" : "card-price card-price-rent";

  return `
    <article class="property-card" data-id="${property.id}" data-type="${property.type}" data-action="${property.action}">
      <a href="property-details.html?id=${property.id}" class="card-link">
        ${cardImageHtml(property)}
        <div class="card-body">
          <div class="card-badges">${getActionBadge(property)}</div>
          <div class="card-price-row">
            <span class="${priceClass}">${formatPrice(property)}</span>
          </div>
          <h3 class="card-title">${property.title}</h3>
          <p class="card-location">📍 ${property.location}</p>
          <div class="card-details">${cardDetailsHtml(property)}</div>
        </div>
      </a>
    </article>
  `;
}

function filterProperties(properties, searchQuery, transaction, category) {
  let filtered = properties.filter((p) => {
    if (transaction === "sale") return p.action === "sale";
    if (transaction === "rent") return p.action === "rent";
    return true;
  });

  if (category && category !== "all") {
    filtered = filtered.filter((p) => p.type === category);
  }

  if (searchQuery && searchQuery.trim()) {
    const q = searchQuery.toLowerCase().trim();
    filtered = filtered.filter(
      (p) =>
        p.title.toLowerCase().includes(q) ||
        p.location.toLowerCase().includes(q) ||
        p.locality.toLowerCase().includes(q) ||
        p.typeLabel.toLowerCase().includes(q)
    );
  }

  return filtered;
}

function renderPropertyGrid(container, properties, emptyMessage) {
  if (!container) return;

  if (properties.length === 0) {
    container.innerHTML = `<div class="no-results"><p>${emptyMessage || "No properties found. Try a different filter or search."}</p></motionless>`;
    container.innerHTML = `<div class="no-results"><p>${emptyMessage || "No properties found. Try a different filter or search."}</p></div>`;
    return;
  }

  container.innerHTML = properties.map((p) => renderPropertyCard(p)).join("");
}

function renderSubFilters(container, transaction, activeCategory, onSelect) {
  if (!container) return;
  const filters = SUB_FILTERS[transaction] || SUB_FILTERS.sale;
  container.innerHTML = filters
    .map(
      (f) =>
        `<button type="button" class="category-chip${f.id === activeCategory ? " active" : ""}" data-category="${f.id}">${f.label}</button>`
    )
    .join("");

  container.querySelectorAll(".category-chip").forEach((chip) => {
    chip.addEventListener("click", () => {
      container.querySelectorAll(".category-chip").forEach((c) => c.classList.remove("active"));
      chip.classList.add("active");
      onSelect(chip.dataset.category || "all");
    });
  });
}

function updateListingsHeader(transaction, count) {
  const heading = document.getElementById("listings-heading");
  const sub = document.getElementById("listings-subheading");
  const countEl = document.getElementById("listings-count");
  const section = document.querySelector(".listings-section");

  if (transaction === "sale") {
    if (heading) heading.textContent = "Properties for Sale in Dehradun";
    if (sub) sub.textContent = "Browse homes, plots & commercial spaces to buy";
    section?.classList.remove("mode-rent");
    section?.classList.add("mode-buy");
  } else {
    if (heading) heading.textContent = "Properties for Rent in Dehradun";
    if (sub) sub.textContent = "Houses, flats, shops, offices & PG accommodations";
    section?.classList.remove("mode-buy");
    section?.classList.add("mode-rent");
  }

  if (countEl) countEl.textContent = count + " listing" + (count !== 1 ? "s" : "");
}

function updateStats() {
  const all = getAllProperties();
  const saleCount = all.filter((p) => p.action === "sale").length;
  const rentCount = all.filter((p) => p.action === "rent").length;
  const totalEl = document.getElementById("stat-total");
  const saleEl = document.getElementById("stat-sale");
  const rentEl = document.getElementById("stat-rent");
  if (totalEl) totalEl.textContent = all.length + "+";
  if (saleEl) saleEl.textContent = saleCount + "+";
  if (rentEl) rentEl.textContent = rentCount + "+";
}

function initHomepage() {
  const grid = document.getElementById("property-grid");
  const searchInput = document.getElementById("search-input");
  const searchBtn = document.getElementById("search-btn");
  const subFiltersEl = document.getElementById("sub-filters");
  const mainTabs = document.querySelectorAll(".transaction-tab");

  let activeTransaction = "sale";
  let activeCategory = "all";

  const params = new URLSearchParams(window.location.search);
  const tabParam = params.get("tab");
  if (tabParam === "rent") activeTransaction = "rent";

  function setMainTab(transaction) {
    activeTransaction = transaction;
    activeCategory = "all";
    mainTabs.forEach((tab) => {
      const isActive = tab.dataset.transaction === transaction;
      tab.classList.toggle("active", isActive);
      tab.setAttribute("aria-selected", isActive ? "true" : "false");
    });
    renderSubFilters(subFiltersEl, transaction, activeCategory, (cat) => {
      activeCategory = cat;
      updateGrid();
    });
    updateGrid();
  }

  function updateGrid() {
    const query = searchInput ? searchInput.value : "";
    const all = getAllProperties();
    const filtered = filterProperties(all, query, activeTransaction, activeCategory);
    const emptyMsg =
      activeTransaction === "sale"
        ? "No properties for sale in this category. Try another filter."
        : "No properties for rent in this category. Try another filter.";
    renderPropertyGrid(grid, filtered, emptyMsg);
    updateListingsHeader(activeTransaction, filtered.length);
  }

  mainTabs.forEach((tab) => {
    tab.addEventListener("click", () => setMainTab(tab.dataset.transaction));
  });

  if (searchBtn) {
    searchBtn.addEventListener("click", (e) => {
      e.preventDefault();
      updateGrid();
    });
  }

  if (searchInput) {
    searchInput.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        e.preventDefault();
        updateGrid();
      }
    });
    searchInput.addEventListener("input", updateGrid);
  }

  updateStats();
  setMainTab(activeTransaction);
}

function initPropertyDetails() {
  const params = new URLSearchParams(window.location.search);
