  }

  document.title = property.title + " | DoonProperties.in";

  const transactionType = getTransactionLabel(property);
  const bannerClass =
    property.type === "pg" ? "transaction-banner banner-pg" : property.action === "sale" ? "transaction-banner banner-sale" : "transaction-banner banner-rent";

  const specs = [{ label: "Transaction", value: transactionType }];
