  const icons = { house: "🏠", apartment: "🏢", plot: "📐", commercial: "🏪", pg: "🛏️" };
  const backLink =
    property.action === "sale"
      ? '<a href="index.html?tab=buy">← Back to Buy listings</a>'
      : '<a href="index.html?tab=rent">← Back to Rent listings</a>';
  const contactLabel = property.action === "sale" ? "Contact Seller" : property.type === "pg" ? "Contact Owner" : "Contact Landlord";

  container.innerHTML = `
    <div class="${bannerClass}">
      ${getActionBadge(property, true)}
      <span class="transaction-banner-text">${transactionType} · ${property.typeLabel}</span>
    </div>
    <div class="detail-layout">
      <div class="detail-gallery">
        <div class="detail-image-main" style="background: linear-gradient(135deg, ${property.imageColor}22, ${property.imageColor}55);">
          <span class="detail-placeholder-icon">${icons[property.type] || "🏠"}</span>
        </div>
