          <h1>${property.title}</h1>
          <p class="detail-location">📍 ${property.location}</p>
          <p class="detail-price ${property.action === "sale" ? "price-sale" : "price-rent"}">${formatPrice(property)}</p>
          <p class="detail-price-note">${property.type === "pg" ? "Monthly rent · PG/Guesthouse" : property.action === "rent" ? "Monthly rent" : "Total price"}</p>
