function initPostAd() {
  const form = document.getElementById("post-ad-form");
  if (!form) return;

  const transactionSelect = document.getElementById("listing-type");
  const typeSelect = document.getElementById("type");
  const pgFields = document.getElementById("pg-fields");
  const standardFields = document.getElementById("standard-fields");
  const plotNote = document.getElementById("plot-note");

  function updateFormForListingType() {
    const listingType = transactionSelect?.value || "sale";

    if (typeSelect) {
      Array.from(typeSelect.options).forEach((opt) => {
        if (!opt.value) return;
        if (listingType === "pg") {
          opt.hidden = opt.value !== "pg";
        } else if (listingType === "sale") {
          opt.hidden = opt.value === "pg";
        } else {
          opt.hidden = opt.value === "plot" || opt.value === "pg";
        }
      });
      if (listingType === "pg") typeSelect.value = "pg";
      else if (typeSelect.value === "pg" || (listingType === "rent" && typeSelect.value === "plot")) {
        typeSelect.value = "";
      }
    }

    if (pgFields) pgFields.hidden = listingType !== "pg";
    if (standardFields) standardFields.hidden = listingType === "pg";
    if (plotNote) plotNote.hidden = listingType !== "sale";

    const priceLabel = document.getElementById("price-label");
    const priceInput = document.getElementById("price");
    if (priceLabel && priceInput) {
      if (listingType === "sale") {
        priceLabel.innerHTML = 'Price (₹) <span class="required">*</span>';
        priceInput.placeholder = "e.g. 12500000 (sale price in rupees)";
      } else if (listingType === "pg") {
        priceLabel.innerHTML = 'Monthly Rent (₹) <span class="required">*</span>';
        priceInput.placeholder = "e.g. 8500 per month";
      } else {
        priceLabel.innerHTML = 'Monthly Rent (₹) <span class="required">*</span>';
        priceInput.placeholder = "e.g. 22000 per month";
      }
    }
  }

  transactionSelect?.addEventListener("change", updateFormForListingType);
  updateFormForListingType();

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const formData = new FormData(form);
    const stored = getStoredProperties();
    const maxId = Math.max(...getAllProperties().map((p) => p.id), 0);

    const listingType = formData.get("listingType") || "sale";
    const typeMap = {
      house: "House / Villa",
      apartment: "Apartment / Flat",
      plot: "Land / Plot",
      commercial: "Commercial",
      pg: "PG / Guesthouse",
    };

    const type = listingType === "pg" ? "pg" : formData.get("type");
    const action = listingType === "sale" ? "sale" : "rent";

    const colors = ["#4CAF50", "#2196F3", "#FF9800", "#9C27B0", "#009688", "#795548"];

    const newProperty = {
      id: maxId + 1,
      title: formData.get("title") || "Property Listing",
      type,
      typeLabel: typeMap[type] || "Property",
      action,
      price: Number(formData.get("price")),
      location: formData.get("location") + ", Dehradun",
      locality: formData.get("location"),
      bedrooms: Number(formData.get("bedrooms")) || 0,
      bathrooms: Number(formData.get("bathrooms")) || 0,
      sqft: Number(formData.get("sqft")) || 0,
      description: formData.get("description") || "",
      contact: formData.get("contact") || "",
      imageColor: colors[Math.floor(Math.random() * colors.length)],
    };

    if (type === "pg") {
      newProperty.pgSharing = formData.get("pgSharing") || "sharing";
    }

    stored.push(newProperty);
    localStorage.setItem("doonProperties", JSON.stringify(stored));

    const successEl = document.getElementById("form-success");
    if (successEl) {
      successEl.hidden = false;
      successEl.scrollIntoView({ behavior: "smooth" });
    }
    form.reset();
    updateFormForListingType();

    const preview = document.getElementById("image-preview");
    if (preview) {
      preview.hidden = true;
      preview.innerHTML = "";
    }

    setTimeout(() => {
      window.location.href = "property-details.html?id=" + newProperty.id;
    }, 1500);
  });

  const imageInput = document.getElementById("image-upload");
  const preview = document.getElementById("image-preview");
  if (imageInput && preview) {
    imageInput.addEventListener("change", () => {
      const file = imageInput.files[0];
      if (file) {
        const reader = new FileReader();
        reader.onload = (ev) => {
          preview.innerHTML = `<img src="${ev.target.result}" alt="Preview" class="upload-preview-img">`;
          preview.hidden = false;
        };
        reader.readAsDataURL(file);
      }
    });
  }
}

document.addEventListener("DOMContentLoaded", () => {
  const page = document.body.dataset.page;
  if (page === "home") initHomepage();
  else if (page === "details") initPropertyDetails();
  else if (page === "post-ad") initPostAd();
});

