function isPgListing(property) {
  return property && property.type === "pg";
}

/** Display label for PG occupancy only */
function getOccupancyLabel(property) {
  if (!isPgListing(property) || !property.occupancy) return null;
  if (property.occupancy === "Both") return "Single/Sharing";
  return property.occupancy;
}

function normalizeProperty(property) {
  const p = { ...property };
  if (!isPgListing(p)) {
    delete p.occupancy;
    delete p.pgSharing;
  } else if (!p.occupancy && p.pgSharing) {
    const map = { single: "Single", sharing: "Sharing", both: "Both" };
    p.occupancy = map[String(p.pgSharing).toLowerCase()] || "Sharing";
    delete p.pgSharing;
  }
  return p;
}

function formatPrice(property) {
  const price = property.price;

  if (isPgListing(property)) {
    const occ = getOccupancyLabel(property);
    const occSuffix = occ ? " (" + occ.toLowerCase() + ")" : "";
    return "₹" + price.toLocaleString("en-IN") + " / month" + occSuffix;
  }

  if (property.action === "rent") {
    return "₹" + price.toLocaleString("en-IN") + " / month";
  }

function getAllProperties() {
  return [...PROPERTIES, ...getStoredProperties()].map(normalizeProperty);
}

