function initPostAd() {
  const form = document.getElementById("post-ad-form");
  if (!form) return;

  const listingTypeSelect = document.getElementById("listing-type");
  const typeSelect = document.getElementById("type");
  const occupancyField = document.getElementById("occupancy-field");
  const occupancySelect = document.getElementById("occupancy");
  const standardFields = document.getElementById("standard-fields");
  const plotNote = document.getElementById("plot-note");

  const ALLOWED_TYPES = {
    sale: ["house", "apartment", "plot", "commercial"],
    rent: ["house", "apartment", "commercial"],
    pg: ["pg", "guesthouse"],
  };

  function updatePropertyTypeOptions(listingType) {
    if (!typeSelect) return;
    const allowed = ALLOWED_TYPES[listingType] || ALLOWED_TYPES.sale;
    let currentValid = false;

    Array.from(typeSelect.options).forEach((opt) => {
      if (!opt.value) return;
      const types = (opt.getAttribute("data-listing-types") || "").split(",");
      const show = types.includes(listingType);
      opt.hidden = !show;
      opt.disabled = !show;
      if (show && opt.value === typeSelect.value) currentValid = true;
    });

    if (listingType === "pg") {
      typeSelect.value = "pg";
    } else if (!currentValid) {
      typeSelect.value = "";
    }
  }

  function updateFormForListingType() {
    const listingType = listingTypeSelect?.value || "sale";
    const isPg = listingType === "pg";

    updatePropertyTypeOptions(listingType);

    if (occupancyField) {
      occupancyField.style.display = isPg ? "block" : "none";
    }
    if (occupancySelect) {
      occupancySelect.required = isPg;
      if (!isPg) occupancySelect.removeAttribute("name");
      else occupancySelect.setAttribute("name", "occupancy");
    }

    if (standardFields) {
      standardFields.style.display = isPg ? "none" : "grid";
    }

    if (plotNote) plotNote.style.display = listingType === "sale" ? "block" : "none";

    const priceLabel = document.getElementById("price-label");
    const priceInput = document.getElementById("price");
    if (priceLabel && priceInput) {
      if (listingType === "sale") {
        priceLabel.innerHTML = 'Price (₹) <span class="required">*</span>';
        priceInput.placeholder = "e.g. 12500000 (sale price in rupees)";
      } else if (listingType === "pg") {
        priceLabel.innerHTML = 'Monthly Rent (₹) <span class="required">*</span>';
        priceInput.placeholder = "e.g. 8500 per month";
      } else {
        priceLabel.innerHTML = 'Monthly Rent (₹) <span class="required">*</span>';
        priceInput.placeholder = "e.g. 22000 per month";
      }
    }
  }

  listingTypeSelect?.addEventListener("change", updateFormForListingType);
  updateFormForListingType();

  form.addEventListener("submit", (e) => {
    e.preventDefault();

    const formData = new FormData(form);
    const stored = getStoredProperties();
    const maxId = Math.max(...getAllProperties().map((p) => p.id), 0);

    const listingType = formData.get("listingType") || "sale";
    const isPgListing = listingType === "pg";
    const typeMap = {
      house: "House / Villa",
      apartment: "Apartment / Flat",
      plot: "Land / Plot",
      commercial: "Commercial",
      pg: "PG",
      guesthouse: "Guesthouse",
    };

    const selectedType = isPgListing ? formData.get("type") || "pg" : formData.get("type");
    const type = isPgListing ? "pg" : selectedType;
    const action = listingType === "sale" ? "sale" : "rent";

    const colors = ["#4CAF50", "#2196F3", "#FF9800", "#9C27B0", "#009688", "#795548"];

    const newProperty = {
      id: maxId + 1,
      title: formData.get("title") || "Property Listing",
      type,
      typeLabel: isPgListing
        ? typeMap[selectedType] || "PG / Guesthouse"
        : typeMap[type] || "Property",
      action,
      price: Number(formData.get("price")),
      location: formData.get("location") + ", Dehradun",
      locality: formData.get("location"),
      bedrooms: isPgListing ? 0 : Number(formData.get("bedrooms")) || 0,
      bathrooms: isPgListing ? 0 : Number(formData.get("bathrooms")) || 0,
      sqft: Number(formData.get("sqft")) || 0,
      description: formData.get("description") || "",
      contact: formData.get("contact") || "",
      imageColor: colors[Math.floor(Math.random() * colors.length)],
    };

    if (isPgListing) {
      newProperty.occupancy = formData.get("occupancy") || "Sharing";
    }

    stored.push(normalizeProperty(newProperty));

