/* DoonProperties.in — Premium visual enhancements */

:root {
  --radius: 16px;
  --radius-sm: 10px;
  --shadow-card: 0 4px 24px rgba(0, 0, 0, 0.08);
  --shadow-card-hover: 0 16px 40px rgba(0, 0, 0, 0.14);
  --purple-pg: #7b1fa2;
  --hero-img: url("https://images.unsplash.com/photo-1600585154340-be6162a9a0f0?auto=format&fit=crop&w=1920&q=85");
}

/* —— Hero premium —— */
.hero-premium {
  min-height: 520px;
  display: flex;
  align-items: center;
  padding: 4rem 1rem 5rem;
  background: none;
  position: relative;
}

.hero-premium::after {
  display: none;
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-image: var(--hero-img);
  background-size: cover;
  background-position: center;
  z-index: 0;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(27, 94, 32, 0.88) 0%, rgba(0, 0, 0, 0.55) 50%, rgba(0, 0, 0, 0.4) 100%);
  z-index: 1;
}

.hero-premium .hero-inner {
  z-index: 2;
  max-width: 720px;
}

.hero-eyebrow {
  font-size: 0.9rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  opacity: 0.95;
  margin-bottom: 0.75rem;
}

.hero-premium h1 {
  font-size: clamp(2rem, 5vw, 3rem);
  margin-bottom: 0.75rem;
  text-shadow: 0 2px 20px rgba(0, 0, 0, 0.3);
}

.hero-sub {
  font-size: 1.1rem;
  opacity: 0.95;
  max-width: 560px;
  margin-bottom: 1.5rem;
  line-height: 1.6;
}

.hero-cta-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-bottom: 1.75rem;
}

.btn-hero-primary {
  background: linear-gradient(135deg, var(--secondary), var(--secondary-dark));
  color: #212121;
  padding: 0.85rem 1.5rem;
  border-radius: var(--radius-sm);
  font-weight: 700;
  box-shadow: 0 4px 20px rgba(255, 160, 0, 0.45);
}

.btn-hero-primary:hover {
  color: #212121;
  transform: translateY(-2px);
}

.btn-hero-outline {
  background: rgba(255, 255, 255, 0.15);
  color: white;
  border: 2px solid rgba(255, 255, 255, 0.7);
  padding: 0.85rem 1.5rem;
  border-radius: var(--radius-sm);
  font-weight: 600;
  backdrop-filter: blur(8px);
}

.btn-hero-outline:hover {
  background: white;
  color: var(--primary-dark);
}

.search-bar-float {
  animation: floatSearch 4s ease-in-out infinite;
  max-width: 100%;
  border-radius: var(--radius);
  position: relative;
  padding-left: 0;
}

@keyframes floatSearch {
  0%,
  100% {
    transform: translateY(0);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.2);
  }
  50% {
    transform: translateY(-6px);
    box-shadow: 0 16px 48px rgba(0, 0, 0, 0.25);
  }
}

.search-bar .search-icon {
  position: absolute;
  left: 1.1rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--text-muted);
  z-index: 1;
  pointer-events: none;
}

.search-bar-float input {
  padding-left: 2.75rem;
}

.btn-primary {
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
}

.btn-secondary {
  background: linear-gradient(135deg, var(--secondary), #ffb74d);
}

.transaction-tab.active[data-transaction="sale"] {
  background: linear-gradient(135deg, var(--primary), var(--primary-light));
}

.transaction-tab.active[data-transaction="rent"] {
  background: linear-gradient(135deg, var(--secondary), #ffb74d);
}

/* —— Why choose us —— */
.why-section {
  background: var(--white);
  margin-top: -2rem;
  position: relative;
  z-index: 3;
  border-radius: var(--radius) var(--radius) 0 0;
  padding-top: 2.5rem;
}

.section-title-center {
  text-align: center;
  margin-bottom: 2rem;
}

.section-title-center h2 {
  font-size: 1.75rem;
  margin-bottom: 0.35rem;
}

.section-title-center p {
  color: var(--text-muted);
}

.why-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}

@media (min-width: 600px) {
  .why-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 900px) {
  .why-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.why-card {
  background: var(--bg);
  padding: 1.5rem;
  border-radius: var(--radius);
  text-align: center;
  transition: transform 0.25s, box-shadow 0.25s;
  border: 1px solid transparent;
}

.why-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-card-hover);
  border-color: rgba(46, 125, 50, 0.2);
}

.why-icon {
  width: 56px;
  height: 56px;
  margin: 0 auto 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, rgba(46, 125, 50, 0.15), rgba(46, 125, 50, 0.05));
  color: var(--primary);
  border-radius: 50%;
  font-size: 1.35rem;
}

.why-icon-gold {
  background: linear-gradient(135deg, rgba(255, 160, 0, 0.2), rgba(255, 160, 0, 0.05));
  color: var(--secondary-dark);
}

.why-icon-purple {
  background: linear-gradient(135deg, rgba(123, 31, 162, 0.15), rgba(123, 31, 162, 0.05));
  color: var(--purple-pg);
}

.why-card h3 {
  font-size: 1rem;
  margin-bottom: 0.5rem;
}

.why-card p {
  font-size: 0.875rem;
  color: var(--text-muted);
  line-height: 1.5;
}

/* —— Stats counters —— */
.stats-section {
  padding: 2rem 0;
}

.stats-counter-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

@media (min-width: 768px) {
  .stats-counter-grid {
    grid-template-columns: repeat(4, 1fr);
  }
}

.stat-counter {
  background: linear-gradient(145deg, var(--white), var(--bg));
  padding: 1.5rem;
  border-radius: var(--radius);
  text-align: center;
  box-shadow: var(--shadow-card);
}

.stat-counter strong {
  font-size: 2rem;
  color: var(--primary);
  font-family: "Poppins", sans-serif;
}

.stat-counter span {
  font-size: 1.5rem;
  color: var(--primary);
  font-weight: 700;
}

.stat-counter p {
  font-size: 0.85rem;
  color: var(--text-muted);
  margin-top: 0.35rem;
}

/* —— Locality chips —— */
.locality-section {
  padding-bottom: 0.5rem;
}

.locality-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 0.6rem;
  justify-content: center;
}

.locality-chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.55rem 1rem;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: 999px;
  font-family: var(--font);
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  transition: all 0.2s;
  box-shadow: var(--shadow);
}

.locality-chip:hover,
.locality-chip.active {
  background: var(--primary);
  border-color: var(--primary);
  color: white;
}

.locality-chip i {
  font-size: 0.8rem;
  opacity: 0.85;
}

.stats-bar-mini {
  margin-top: 1rem;
}

/* —— Property cards premium —— */
.property-card {
  border-radius: var(--radius);
  box-shadow: var(--shadow-card);
  border: 1px solid rgba(0, 0, 0, 0.04);
}

.property-card:hover {
  transform: translateY(-8px);
  box-shadow: var(--shadow-card-hover);
}

.card-link {
  display: flex;
  flex-direction: column;
  height: 100%;
}

.card-image-wrap {
  position: relative;
  aspect-ratio: 4 / 3;
  overflow: hidden;
  border-radius: var(--radius) var(--radius) 0 0;
  background: var(--bg);
}

.card-slider {
  position: relative;
  width: 100%;
  height: 100%;
}

.card-slider-track {
  display: flex;
  height: 100%;
  transition: transform 0.35s ease;
}

.card-slide {
  min-width: 100%;
  height: 100%;
  object-fit: cover;
  opacity: 0;
  transition: opacity 0.3s;
}

.card-slide.loaded {
  opacity: 1;
}

.card-slide.skeleton {
  background: linear-gradient(90deg, #eee 25%, #f5f5f5 50%, #eee 75%);
  background-size: 200% 100%;
  animation: shimmer 1.2s infinite;
}

@keyframes shimmer {
  0% {
    background-position: 200% 0;
  }
  100% {
    background-position: -200% 0;
  }
}

.card-image-fallback {
  position: absolute;
  inset: 0;
  display: none;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  z-index: 0;
}

.card-image-wrap.is-fallback .card-image-fallback {
  display: flex;
}

.card-image-wrap.is-fallback .card-slider {
  opacity: 0;
  pointer-events: none;
}

.card-image-fallback i {
  font-size: 2.5rem;
  opacity: 0.5;
}

.card-slider-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 32px;
  height: 32px;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.92);
  color: var(--text);
  cursor: pointer;
  z-index: 3;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: opacity 0.2s;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.15);
}

.property-card:hover .card-slider-btn {
  opacity: 1;
}

.card-slider-btn.prev {
  left: 8px;
}

.card-slider-btn.next {
  right: 8px;
}

.card-slider-dots {
  position: absolute;
  bottom: 10px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 6px;
  z-index: 3;
}

.card-slider-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  border: none;
  background: rgba(255, 255, 255, 0.5);
  cursor: pointer;
  padding: 0;
}

.card-slider-dot.active {
  background: white;
  width: 18px;
  border-radius: 4px;
}

.wishlist-btn {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 36px;
  height: 36px;
  border: none;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.95);
  color: #e53935;
  cursor: pointer;
  z-index: 4;
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
  transition: transform 0.2s;
}

.wishlist-btn:hover {
  transform: scale(1.1);
}

.wishlist-btn.active i {
  font-weight: 900;
}

.badge-featured {
  position: absolute;
  top: 12px;
  left: 12px;
  background: linear-gradient(135deg, var(--secondary), var(--secondary-dark));
  color: #212121;
  font-size: 0.65rem;
  font-weight: 800;
  padding: 0.35rem 0.65rem;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  z-index: 4;
  box-shadow: 0 2px 8px rgba(255, 160, 0, 0.4);
}

.card-body {
  padding: 1.15rem;
  flex: 1;
}

.card-price-row {
  margin-bottom: 0.35rem;
}

.card-price {
  font-size: 1.35rem !important;
  font-weight: 800 !important;
  display: flex;
  align-items: center;
  gap: 0.35rem;
}

.card-price i {
  font-size: 1rem;
  opacity: 0.85;
}

.card-amenities {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-top: 0.65rem;
  padding-top: 0.65rem;
  border-top: 1px solid var(--border);
}

.amenity-icon {
  font-size: 0.75rem;
  color: var(--text-muted);
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}

.amenity-icon i {
  color: var(--primary);
  width: 14px;
}

.detail-item i {
  margin-right: 0.2rem;
  color: var(--primary);
  width: 14px;
}

/* —— CTA banner —— */
