  wifi: { icon: "fa-wifi", label: "Wi-Fi" },
  meals: { icon: "fa-utensils", label: "Meals" },
};

const DEFAULT_AMENITIES = {
  house: ["parking", "security", "garden"],
  apartment: ["parking", "security", "lift"],
  plot: [],
  commercial: ["parking", "security"],
  pg: ["wifi", "meals", "security"],
};

