  house: "fa-house",
  apartment: "fa-building",
  plot: "fa-map",
  commercial: "fa-store",
  pg: "fa-bed",
};

function getPropertyImages(property) {
  if (property.images && property.images.length) return property.images;
  const gallery = GALLERY_BY_TYPE[property.type] || GALLERY_BY_TYPE.house;
  return gallery.map((url, i) => url + (url.includes("?") ? "&" : "?") + "sig=" + property.id + "-" + i);
}

function getPropertyAmenities(property) {
  if (property.amenities && property.amenities.length) return property.amenities;
  return DEFAULT_AMENITIES[property.type] || [];
}

function isFeatured(property) {
  return property.featured === true || FEATURED_IDS.includes(property.id);
}

