function enrichProperty(property) {
  const p = normalizeProperty(property);
  p.images = getPropertyImages(p);
  p.amenities = getPropertyAmenities(p);
  if (p.featured === undefined) p.featured = FEATURED_IDS.includes(p.id);
  return p;
}

function getAllProperties() {
  return [...PROPERTIES, ...getStoredProperties()].map(enrichProperty);
}

