function setCardSlide(wrap, index) {
  const track = wrap.querySelector(".card-slider-track");
  const slides = wrap.querySelectorAll(".card-slide");
  const dots = wrap.querySelectorAll(".card-slider-dot");
  const total = slides.length;
  if (!total) return;
  const i = ((index % total) + total) % total;
  if (track) track.style.transform = `translateX(-${i * 100}%)`;
  dots.forEach((d, j) => d.classList.toggle("active", j === i));
  wrap.dataset.slideIndex = String(i);
}

function initCardInteractions(container) {
  if (!container) return;

  container.querySelectorAll(".card-image-wrap").forEach((wrap) => {
    const total = Number(wrap.querySelector(".card-slider")?.dataset.slides || 1);
    if (total > 1) setCardSlide(wrap, 0);
  });

  container.addEventListener(
    "click",
    (e) => {
      const wish = e.target.closest(".wishlist-btn");
      if (wish) {
        e.preventDefault();
        e.stopPropagation();
        wish.classList.toggle("active");
        const icon = wish.querySelector("i");
        if (icon) {
          icon.classList.toggle("fa-regular", !wish.classList.contains("active"));
          icon.classList.toggle("fa-solid", wish.classList.contains("active"));
        }
        return;
      }

      const wrap = e.target.closest(".card-image-wrap");
      if (!wrap) return;

      if (e.target.closest(".card-slider-btn.prev")) {
        e.preventDefault();
        e.stopPropagation();
        const cur = Number(wrap.dataset.slideIndex || 0);
        setCardSlide(wrap, cur - 1);
        return;
      }
      if (e.target.closest(".card-slider-btn.next")) {
        e.preventDefault();
        e.stopPropagation();
        const cur = Number(wrap.dataset.slideIndex || 0);
        setCardSlide(wrap, cur + 1);
        return;
      }
      const dot = e.target.closest(".card-slider-dot");
      if (dot) {
        e.preventDefault();
        e.stopPropagation();
        setCardSlide(wrap, Number(dot.dataset.dot));
      }
    },
    true
  );
}

function initStatCounters() {
  const counters = document.querySelectorAll(".counter-value");
  if (!counters.length) return;

  const animate = (el) => {
    const target = Number(el.dataset.target) || 0;
    const duration = 1200;
    const start = performance.now();
    const step = (now) => {
      const progress = Math.min((now - start) / duration, 1);
      el.textContent = Math.floor(progress * target);
      if (progress < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  };

  const observer = new IntersectionObserver(
    (entries) => {
      entries.forEach((entry) => {
        if (entry.isIntersecting) {
          animate(entry.target);
          observer.unobserve(entry.target);
        }
      });
    },
    { threshold: 0.3 }
  );
  counters.forEach((c) => observer.observe(c));
}

function initLocalityChips(searchInput, onSearch) {
  const chips = document.querySelectorAll(".locality-chip");
  chips.forEach((chip) => {
    chip.addEventListener("click", () => {
      chips.forEach((c) => c.classList.remove("active"));
      chip.classList.add("active");
      const locality = chip.dataset.locality || "";
      if (searchInput) searchInput.value = locality;
      onSearch?.();
      document.getElementById("listings")?.scrollIntoView({ behavior: "smooth" });
    });
  });
}

